SAFETY_DISCLAIMER = (
    "PRELIMINARY AI OBSERVATION ONLY: This visual assessment is generated by an automated model "
    "and must NOT be relied upon as a replacement for qualified OSHA/NEBOSH safety inspections. "
    "Observations are limited strictly to visible image areas. An absence of identified hazards does not "
    "imply site compliance. Qualified human review is required before closing any findings."
)

CRACK_DISCLAIMER = (
    "NON-STRUCTURAL VISUAL ESTIMATE ONLY: Ordinary photographic analysis cannot determine subsurface integrity, "
    "depth, or calibrated crack width. A licensed structural or civil engineer must inspect cracks showing "
    "diagonal shear patterns, active settlement, or displacement before any load-bearing decisions are made."
)

PLANNING_DISCLAIMER = (
    "PLANNING SUGGESTION ONLY: AI-generated durations, Work Breakdown Structures, and budget allocations "
    "are exploratory benchmarks based on standard industry averages. Local soil conditions, municipal permit cycles, "
    "material availability, and weather must be verified by a licensed Project Manager / Quantity Surveyor."
)

ASSISTANT_DISCLAIMER = (
    "General educational and reference guidance. For high-risk decisions (such as structural load calculations, "
    "fire separation ratings, foundation underpinning, and high-voltage electrical safety), consult a licensed professional."
)

class AIService:
    @staticmethod
    def get_configured_provider() -> str:
        if settings.GEMINI_API_KEY and settings.GEMINI_API_KEY.strip():
            return "gemini"
        if settings.OPENAI_API_KEY and settings.OPENAI_API_KEY.strip():
            return "openai"
        return "demo"

    @classmethod
    async def analyze_site_safety(cls, image_path: str, categories: List[str] = None) -> Tuple[SafetyAnalysisData, str]:
        """
        Returns (SafetyAnalysisData, mode: 'ai' | 'demo')
        """
        provider = cls.get_configured_provider()
        
        if provider == "demo":
            return cls._get_demo_safety_analysis(image_path), "demo"
        
        # If API key is present, attempt live multimodal AI call
        try:
            if provider == "gemini":
                result = await cls._call_gemini_safety(image_path, categories)
                return result, "ai"
            elif provider == "openai":
                result = await cls._call_openai_safety(image_path, categories)
                return result, "ai"
        except Exception as e:
            # According to Section 16: "Never silently substitute demo results for failed live AI requests."
            raise RuntimeError(f"Live AI safety analysis failed via {provider}: {str(e)}")
        
        return cls._get_demo_safety_analysis(image_path), "demo"

    @classmethod
    async def analyze_cracks(cls, image_path: str, structure_type: str = "Wall", notes: str = "") -> Tuple[CrackAnalysisData, str]:
        """
        Returns (CrackAnalysisData, mode: 'ai' | 'demo')
        """
        provider = cls.get_configured_provider()
        
        if provider == "demo":
            return cls._get_demo_crack_analysis(image_path, structure_type), "demo"
        
        try:
            if provider == "gemini":
                result = await cls._call_gemini_cracks(image_path, structure_type, notes)
                return result, "ai"
            elif provider == "openai":
                result = await cls._call_openai_cracks(image_path, structure_type, notes)
                return result, "ai"
        except Exception as e:
            raise RuntimeError(f"Live AI crack analysis failed via {provider}: {str(e)}")
        
        return cls._get_demo_crack_analysis(image_path, structure_type), "demo"

    @classmethod
    async def chat_assistant(cls, user_message: str, project_context: str = "") -> Tuple[AssistantChatResponse, str]:
        provider = cls.get_configured_provider()
        
        if provider == "demo":
            return cls._get_demo_assistant_response(user_message), "demo"
        
        try:
            if provider == "gemini":
                response = await cls._call_gemini_chat(user_message, project_context)
                return response, "ai"
            elif provider == "openai":
                response = await cls._call_openai_chat(user_message, project_context)
                return response, "ai"
        except Exception as e:
            raise RuntimeError(f"Assistant AI query failed via {provider}: {str(e)}")
            
        return cls._get_demo_assistant_response(user_message), "demo"

    # --- Live API Call Implementations ---
    @classmethod
    async def _call_gemini_safety(cls, image_path: str, categories: List[str]) -> SafetyAnalysisData:
        with open(image_path, "rb") as f:
            b64_image = base64.b64encode(f.read()).decode("utf-8")
        
        prompt = (
            "You are an expert construction site safety auditor. Analyze this construction image for safety hazards. "
            f"Focus on categories: {', '.join(categories) if categories else 'PPE, Fall Hazards, Guardrails, Scaffolding, Housekeeping, Equipment'}. "
            "Output strictly valid JSON with no markdown wrapping matching this structure: "
            "{"
            "  \"analysis_type\": \"safety\","
            "  \"summary\": \"Brief summary of observations.\","
            "  \"overall_severity\": \"low\" | \"medium\" | \"high\" | \"critical\","
            "  \"findings\": ["
            "    {"
            "      \"category\": \"Category name\","
            "      \"description\": \"Specific visual finding\","
            "      \"severity\": \"low\" | \"medium\" | \"high\" | \"critical\","
            "      \"recommended_action\": \"Remediation step\","
            "      \"suggested_priority\": \"Immediate\" | \"High\" | \"Normal\","
            "      \"confidence\": 0.85"
            "    }"
            "  ],"
            "  \"limitations\": [\"Observable view is limited to camera frame.\"]"
            "}"
        )
        
        url = f"https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key={settings.GEMINI_API_KEY}"
        payload = {
            "contents": [
                {
                    "parts": [
                        {"text": prompt},
                        {
                            "inline_data": {
                                "mime_type": "image/jpeg",
                                "data": b64_image
                            }
                        }
                    ]
                }
            ],
            "generationConfig": {"temperature": 0.2, "response_mime_type": "application/json"}
        }
        
        async with httpx.AsyncClient(timeout=30.0) as client:
            resp = await client.post(url, json=payload)
            if resp.status_code != 200:
                raise Exception(f"Gemini API returned code {resp.status_code}: {resp.text}")
            
            res_json = resp.json()
            raw_text = res_json["candidates"][0]["content"]["parts"][0]["text"]
            data = json.loads(raw_text)
            return SafetyAnalysisData(
                analysis_type="safety",
                summary=data.get("summary", "Image evaluated for site safety hazards."),
                overall_severity=data.get("overall_severity", "medium"),
                findings=[SafetyFinding(**f) for f in data.get("findings", [])],
                limitations=data.get("limitations", ["Visual assessment limited to camera perspective."]),
                disclaimer=SAFETY_DISCLAIMER
            )

    @classmethod
    async def _call_gemini_cracks(cls, image_path: str, structure_type: str, notes: str) -> CrackAnalysisData:
        with open(image_path, "rb") as f:
            b64_image = base64.b64encode(f.read()).decode("utf-8")
        
        prompt = (
            f"You are a forensic civil engineer analyzing a concrete/masonry image of structure type: {structure_type}. "
            f"Notes: {notes}. "
            "Output strictly valid JSON with no markdown wrapping matching this structure: "
            "{"
            "  \"analysis_type\": \"crack_detection\","
            "  \"structure_type\": \"" + structure_type + "\","
            "  \"summary\": \"Summary of crack observations.\","
            "  \"overall_severity\": \"low\" | \"medium\" | \"high\" | \"critical\","
            "  \"observations\": ["
            "    {"
            "      \"crack_type\": \"Hairline / Diagonal Shear / Settlement / Flexural\","
            "      \"location_in_image\": \"Image zone description\","
            "      \"appearance\": \"Visual description\","
            "      \"severity\": \"low\" | \"medium\" | \"high\" | \"critical\","
            "      \"recommended_action\": \"Specific follow-up engineering action\","
            "      \"confidence\": 0.88"
            "    }"
            "  ],"
            "  \"limitations\": [\"No calibrated scale reference present in image.\"]"
            "}"
        )
        
        url = f"https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key={settings.GEMINI_API_KEY}"
        payload = {
            "contents": [
                {
                    "parts": [
                        {"text": prompt},
                        {
                            "inline_data": {
                                "mime_type": "image/jpeg",
                                "data": b64_image
                            }
                        }
                    ]
                }
            ],
            "generationConfig": {"temperature": 0.2, "response_mime_type": "application/json"}
        }
        
        async with httpx.AsyncClient(timeout=30.0) as client:
            resp = await client.post(url, json=payload)
            if resp.status_code != 200:
                raise Exception(f"Gemini API returned code {resp.status_code}: {resp.text}")
            
            res_json = resp.json()
            raw_text = res_json["candidates"][0]["content"]["parts"][0]["text"]
            data = json.loads(raw_text)
            return CrackAnalysisData(
                analysis_type="crack_detection",
                structure_type=structure_type,
                summary=data.get("summary", "Surface visual assessment completed."),
                overall_severity=data.get("overall_severity", "medium"),
                observations=[CrackObservation(**obs) for obs in data.get("observations", [])],
                limitations=data.get("limitations", ["Scale not calibrated; subsurface reinforcement uninspected."]),
                calibrated_measurement_available=False,
                disclaimer=CRACK_DISCLAIMER
            )

    @classmethod
    async def _call_gemini_chat(cls, user_message: str, project_context: str) -> AssistantChatResponse:
        system_instruction = (
            "You are BuildSense AI Construction Assistant, an expert advisor on construction engineering, OSHA safety, "
            "concrete curing, scheduling, quality control, and building documentation. "
            "Distinguish educational information from site-specific engineering certifications. Always advise consulting "
            "licensed engineers for critical structural, fire, and electrical decisions."
        )
        context_block = f"\nCurrent Active Project Context: {project_context}" if project_context else ""
        full_prompt = f"{system_instruction}{context_block}\n\nUser Question: {user_message}"
        
        url = f"https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key={settings.GEMINI_API_KEY}"
        payload = {
            "contents": [{"parts": [{"text": full_prompt}]}],
            "generationConfig": {"temperature": 0.4}
        }
        
        async with httpx.AsyncClient(timeout=25.0) as client:
            resp = await client.post(url, json=payload)
            if resp.status_code != 200:
                raise Exception(f"Gemini API returned code {resp.status_code}: {resp.text}")
            res_json = resp.json()
            content = res_json["candidates"][0]["content"]["parts"][0]["text"]
            
            return AssistantChatResponse(
                role="assistant",
                content=content,
                suggestions=[
                    "What are curing standards for high-strength concrete in hot weather?",
                    "Generate a 5-step checklist for pre-pour slab inspection.",
                    "What OSHA requirements govern scaffolding toe-boards and guardrails?"
                ],
                disclaimer=ASSISTANT_DISCLAIMER
            )

