    @classmethod
    def _get_demo_assistant_response(cls, user_message: str) -> AssistantChatResponse:
        lower = user_message.lower()
        if "concrete" in lower or "curing" in lower:
            answer = (
                "### Concrete Curing & Quality Control Best Practices\n\n"
                "**1. Standard Curing Durations:**\n"
                "- Ordinary Portland Cement (OPC): Minimum 7 days continuous wet curing.\n"
                "- Mineral Admixtures (Fly ash, Slag / GGBS): Minimum 10–14 days due to slower pozzolanic hydration.\n\n"
                "**2. Hot Weather Precautions (> 32°C / 90°F):**\n"
                "- Prevent plastic shrinkage cracking by applying aliphatic foggers or curing compounds immediately post-screeding.\n"
                "- Schedule pours during cooler hours (early dawn or dusk).\n"
                "- Keep slump loss in check using polycarboxylate-based retarding superplasticizers.\n\n"
                "> [!NOTE]\n"
                "> For structural post-tensioned slabs or mass pours exceeding 1 meter depth, implement a thermal monitoring plan to ensure the core-to-surface temperature gradient remains below 20°C."
            )
        elif "safety" in lower or "ppe" in lower or "osha" in lower:
            answer = (
                "### Construction Safety & OSHA Focus Four Overview\n\n"
                "The OSHA 'Focus Four' hazards account for over 60% of construction fatalities:\n\n"
                "1. **Falls (Leading Cause):** Fall protection required at 6 ft (1.8m) above lower level. Guardrails, safety nets, or Personal Fall Arrest Systems (PFAS) must be engineered.\n"
                "2. **Caught-In / Between:** Trench excavations over 5 ft (1.5m) must feature trench boxes, shoring, or proper benching/sloping.\n"
                "3. **Struck-By:** High-visibility vest (ANSI Class 2/3), hard hat, and dedicated vehicle spotters in active crane/excavator radii.\n"
                "4. **Electrocution:** Maintain 10-foot minimum clearance from overhead lines up to 50kV. All temporary 120V site power must use Ground Fault Circuit Interrupters (GFCI).\n\n"
                "*Qualified Safety Officers must conduct daily morning toolbox talks before high-risk operations.*"
            )
        elif "plan" in lower or "schedule" in lower or "delay" in lower:
            answer = (
                "### Project Planning & Delay Mitigation Framework\n\n"
                "1. **Critical Path Method (CPM):** Continuously monitor activities with zero total float. Delays on foundation, structural frame, or dry-in envelope directly shift the substantial completion date.\n"
                "2. **Lookahead Scheduling:** Maintain a rolling 3-week to 6-week lookahead schedule with trade trade-partners to resolve RFIs and material lead-time bottlenecks.\n"
                "3. **Daily Delay Logging:** Accurately document weather days (precipitation, wind exceeding crane thresholds), submittal approvals, and unforeseen site conditions in your daily reports to support contractual delay claims."
            )
        else:
            answer = (
                f"### BuildSense Advisory on: *\"{user_message.strip()[:80]}\"*\n\n"
                "In commercial and infrastructure construction, standard project workflows emphasize:\n\n"
                "- **Submittals & RFIs:** Ensure shop drawings, mix designs, and mill certifications are approved prior to material mobilization.\n"
                "- **Quality Assurance / Quality Control (QA/QC):** Establish inspection and test plans (ITPs) with pre-pour, MEP rough-in, and pre-drywall hold points.\n"
                "- **Integrated Project Controls:** Align task sequencing with earned value management (EVM) to track schedule performance index (SPI) and cost performance index (CPI).\n\n"
                "Feel free to ask for specific inspection checklists, material specifications, or estimation formulas."
            )

        return AssistantChatResponse(
            role="assistant",
            content=answer,
            suggestions=[
                "How do I prepare for a pre-pour concrete inspection?",
                "What are the safety requirements for working at heights above 2 meters?",
                "Explain the Critical Path Method (CPM) in construction scheduling."
            ],
            disclaimer=ASSISTANT_DISCLAIMER
        )
